INSERT INTO banners (title, image_url, target_url, sort_order, starts_at, ends_at, is_active) SELECT 'Khai trương mùa mới – giảm đến 15% điện lạnh', 'http://localhost:8080/uploads/banners/cdb116d52a63ad3783d7e68f2b47a0f2.png', '/products', 1, UTC_TIMESTAMP() - INTERVAL 10 DAY, UTC_TIMESTAMP() + INTERVAL 50 DAY, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM banners WHERE title = 'Khai trương mùa mới – giảm đến 15% điện lạnh');
INSERT INTO banners (title, image_url, target_url, sort_order, starts_at, ends_at, is_active) SELECT 'Tủ lạnh Inverter tiết kiệm điện', 'http://localhost:8080/uploads/banners/81d1d8fff61d3813a94bafe2d985e665.png', '/products?category=tu-lanh', 2, UTC_TIMESTAMP() - INTERVAL 5 DAY, UTC_TIMESTAMP() + INTERVAL 60 DAY, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM banners WHERE title = 'Tủ lạnh Inverter tiết kiệm điện');
