INSERT INTO banners (title, image_url, target_url, sort_order, starts_at, ends_at, is_active) SELECT 'Ưu đãi sắp tới (chưa bắt đầu)', 'http://localhost:8080/uploads/banners/f3394c952e3d4048150a6d1cb7452d5b.png', '/products', 5, UTC_TIMESTAMP() + INTERVAL 20 DAY, UTC_TIMESTAMP() + INTERVAL 50 DAY, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM banners WHERE title = 'Ưu đãi sắp tới (chưa bắt đầu)');
